<div class="page-heading"><div><p class="context">Poste de garde</p><h1>Passages camions</h1><p>Une chronologie continue, de l’arrivée au départ.</p></div></div>
<details class="panel editor"><summary>Enregistrer une arrivée</summary><?php startForm('arrive'); ?><div class="form-grid"><?php inputField('reference','Référence du passage');selectField('appointment_id','Rendez-vous (reprend le véhicule et le chauffeur)',$catalog->options('appointment'),'',true);selectField('driver_id','Chauffeur sans rendez-vous',$catalog->options('driver'),'',true);selectField('vehicle_id','Véhicule sans rendez-vous',$catalog->options('vehicle'),'',true);selectField('trailer_id','Remorque',$catalog->options('vehicle'),'',true);selectField('operation','Opération',[['id'=>'reception','label'=>'Réception'],['id'=>'expedition','label'=>'Expédition']],'reception'); ?></div><button>Enregistrer l’arrivée</button></form></details>
<form class="filters" method="get"><input type="hidden" name="page" value="visits"><?php periodFields();selectField('carrier_id','Transporteur',$catalog->options('carrier'),$_GET['carrier_id']??'',true);selectField('status','État',array_map(fn($v)=>['id'=>$v,'label'=>Catalog::VALUES[$v]],['arrived','checked','parking','called','working','finished','departed','rejected']),$_GET['status']??'',true);inputField('q','Passage, plaque ou chauffeur',$_GET['q']??'','search',false);selectField('sort','Tri',[['id'=>'recent','label'=>'Arrivées récentes'],['id'=>'wait','label'=>'Attente décroissante']],$_GET['sort']??'recent');filterEnd('visits'); ?>
<?php $result=$reports->visits($_GET);foreach($result['rows'] as $v): ?><article class="panel visit"><div class="section-heading"><div><h2><?= h($v['reference']) ?></h2><p><?= h($v['carrier_name'].' / '.$v['plate'].' / '.$v['driver_name']) ?></p></div><?= badge($v['status']) ?></div><div class="timeline"><?php foreach($db->all('SELECT state,happened_at FROM visit_event WHERE visit_id=? ORDER BY happened_at,id',[$v['id']]) as $e): ?><span><strong><?= h(Catalog::VALUES[$e['state']]) ?></strong><small><?= h(substr($e['happened_at'],11,5)) ?></small></span><?php endforeach; ?></div><p class="muted">Attente : <?= h($v['wait_minutes']??'en cours') ?> min · Immobilisation : <?= h($v['immobilized_minutes']??'en cours') ?> min<?php if($v['appointment_id']): $scheduled=$db->scalar('SELECT starts_at FROM appointment WHERE id=?',[$v['appointment_id']]); ?> · Retard à l’arrivée : <?= h(max(0,(strtotime($v['arrived_at'])-strtotime($scheduled))/60)) ?> min<?php else: ?> · Sans rendez-vous<?php endif; ?></p><p><?= h($v['document_note']) ?></p>
<?php $next=['arrived'=>['checked','rejected'],'checked'=>['parking','called'],'parking'=>['called'],'called'=>['working'],'working'=>['finished'],'finished'=>['departed']];foreach($next[$v['status']]??[] as $state){startForm('transition',['id'=>$v['id'],'next'=>$state],'inline-form');if($state==='called')selectField('dock_id','Quai',$catalog->options('dock'));if(in_array($state,['checked','rejected'],true))inputField('document_note','Résultat documentaire'); ?><button class="<?= $state==='rejected'?'secondary':'' ?>"><?= h(Catalog::VALUES[$state]) ?></button></form><?php } ?></article><?php endforeach;if(!$result['rows']): ?><p class="empty">Aucun passage pour cette période.</p><?php endif;pagination($result['total'],$result['page']);exportPrint('visits'); ?>
